#!/bin/bash
#SBATCH --job-name=s45_T_res_rq9e4
#SBATCH --cpus-per-task=8 --mem=96G --time=96:00:00
#SBATCH --output=s45_%x_%j.out
# Section 4.5 run T_res_rq9e4 (HotpotQA task training from the final R pair; write mode Hidden Residuals, every 4th layer; encoder Qwen/Qwen3.5-4B). Generated by jobs/make_jobs.py from jobs/job_template.sh: edit the template, not this file.
# ONE H200. Add the cluster's account / partition / GPU flags on the sbatch line (never --export=ALL; never mit_preemptable):
#   CSAIL:  cd /data/scratch-fast/ngom/sec45 && sbatch --export=NIL --account=quanta --partition=quanta-h200 --qos=quanta-main --gpus=1 jobs/<folder>/T_res_rq9e4.sh
#   ORCD:   cd /home/ngom/orcd/scratch/activation/sec45 && sbatch --export=NIL --partition=mit_normal_gpu --gres=gpu:h200:1 jobs/<folder>/T_res_rq9e4.sh
#   EC2 (SkyPilot, instance role for S3): bash T_res_rq9e4.sh
# Inputs are PRE-STAGED under the work root W by jobs/stage.sh (code bundle, data, HF weights) and, for T, jobs/stage_init.sh (R's
# final pair + R's DONE). No S3 on CSAIL / ORCD; outputs stay in $W/runs/T_res_rq9e4 and jobs/pull.sh brings them back. On EC2 (or with
# SEC45_USE_S3=1) the job fetches missing inputs from S3 and uploads its outputs every 15 minutes and at the end.
# v4 (Oct 27): RESUMABLE. Every CKPT_EVERY updates the trainer publishes one recovery slot (pair + optimizer.pt + update count +
# penalty RNG state; the previous slot is deleted only after the new one is published). Resubmitting this same script after a
# crash / preemption / time limit continues the run exactly from the last slot (sec45_train --resume-if-possible): same order,
# schedule and penalty draws. A folder without a slot (died before the first save) is moved aside to <folder>.prev_<time>.
# Disk: R keeps only ckpt/final; S/T link each K-update pair into ckpt/, the eval watcher evaluates it during training and then
# deletes it; optimizer.pt exists only in the recovery slot and is deleted at the end. DONE is written LAST, after ckpt/final is
# complete: {"stop_reason", "valid", "update", "final_sha256", "attempts", ...}. Exit 0 = valid, 3 = finished but INVALID,
# other = failed or stopped (no DONE: resubmit to continue). A run with DONE is not rerun. Slurm limit 96 h (ORCD: pass
# --time=6:00:00 on the sbatch line; the run continues in the next job).
set -uo pipefail
export PATH=${PATH:-/usr/local/bin:/usr/bin:/bin}      # sbatch --export=NIL may leave PATH unset
# ============================== settings (values marked __P0_...__ come from the P0 probe) ==============================
RUN=T_res_rq9e4; KIND=task; MODE=res                      # KIND: probe | recon | task; MODE: in | res | kv
STEPS=${SEC45_STEPS:-5600}                          # optimizer updates (items = STEPS x 8, one pass)
TRAIN_SECONDS=${SEC45_TRAIN_SECONDS:-864000}         # backstop of ONE attempt (large: the cluster's job limit stops a job, the next job resumes)
CKPT_EVERY=${SEC45_CKPT_EVERY:-800}            # recovery slot every K updates; S/T: also the accuracy evals (every K updates + the end)
MICRO=${SEC45_MICRO_BATCH:-1}                     # examples per padded reader forward (ran on the longest items in P0)
GPU_MATCH="exact:NVIDIA RTX PRO 6000 Blackwell Server Edition"                                       # exact:<nvidia-smi name>[|<alias>...] (the P0 values were measured there) | contains:<text>
PAIR_GB=2.35                                       # size of one saved pair (P0), for the free-disk check
OPT_GB=6.5                                         # size of optimizer.pt (the resume test), for the free-disk check
INIT=R_res_rq9e4                                            # fresh | R_<mode> (T: R's final pair, staged by jobs/stage_init.sh)
REPORT_EVERY=${SEC45_REPORT_EVERY:-200}                 # held-out panel every N updates (v5: 200)
STEP0_EVAL=${SEC45_STEP0_EVAL:-1}                       # T only: accuracy of the starting pair (update 0) before training
ENC_LR=5e-5; READER_LR=2e-5; EPU=8; WARMUP=50   # pre-rebuttal (2026-11-09): rates are recipe choices (hill-climbing allowed); READER_LR 0 = frozen reader
PENALTY=1.0; SEED=0                          # no-context penalty weight (applies only while the reader trains); data order / sampling seed
LOSS=""; TARGETS=""   # 2026-11-11: task loss (empty = sft; kl = to the gold-view teacher: the reader at the start reading the gold passages); target replies file under $W (empty = answer-only)
EVAL_SPLIT=${SEC45_EVAL_SPLIT:-dev1000}; EVAL_MAX_NEW=${SEC45_EVAL_MAX_NEW:-256}      # pre-rebuttal: one scorer for every arm (dev1000 for choices, test1000 for reported numbers), cap 256
#   (user 10-27: a truly frozen reader, never a tiny rate like 1e-12; the trainer then skips its gradients and the no-context penalty)
READER_ID=${SEC45_READER_ID:-Qwen/Qwen3.5-9B}   # §3.5: Qwen/Qwen3-4B-Instruct-2507; retrieval: Qwen/Qwen3.5-9B
RES_LAYERS="all"; TASK_K=""; EVAL_K=""; LINEAR_SKIP="1"; RATIO=""   # RATIO (2026-11-11): compression ratio, empty = 0.1; retrieval (2026-11-09): reader layers of the res mode (all = every full-attention layer), passages per item (k or a mix), eval k, least-squares row head for a fresh pair
ENCODER_ID=Qwen/Qwen3.5-4B                                    # v6: empty = the encoder is a copy of the reader; else a smaller encoder (SEC45_ENCODER; in/res only)
S3=${SEC45_S3:-s3://general-bucket-aln/activation-context-data/pre_rebuttal_20261109/sec35}
BUNDLE=${SEC45_BUNDLE:-sec35_code_v5.tar.gz}                        # code bundle under $W/code/ (jobs/make_bundle.py; staged by jobs/stage.sh)
RECON_DATA=fineweb_recon_v1; TASK_DATA=hotpot_tasks_v2  # under $W/data/ (hotpot_tasks_v2 = v1 + dev1000 + test1000; rq_tasks_v1 = retrieval rows with top200)
# ========================================================================================================================
no() { echo "$(date -u +%FT%TZ) REFUSED: $*" >&2; exit 2; }
for v in "$STEPS" "$TRAIN_SECONDS" "$CKPT_EVERY" "$MICRO" "$GPU_MATCH" "$PAIR_GB" "$OPT_GB"; do case "$v" in *__P0*|'') no "a P0 value is not filled in ($v): run the P0 probes, then python jobs/make_jobs.py --probes .../probe_summary_*.json";; esac; done
# ---- where (cluster defaults; SEC45_WORK / SEC45_PY / SEC45_HF_HOME override) ----
if [ -n "${SEC45_WORK:-}" ]; then W=$SEC45_WORK; CL=custom
elif [ -d /data/scratch-fast/ngom ]; then W=/data/scratch-fast/ngom/sec35; CL=csail   # /data/scratch/ngom is over its quota (10-26)
elif [ -d /home/ngom/orcd/scratch/activation ]; then W=/home/ngom/orcd/scratch/activation/sec35; CL=orcd
else W=$HOME/sec35; CL=ec2; fi
case $CL in
  csail) PYC=(/data/scratch/ngom/activation/venv/bin/python); [ "$(uname -m)" = aarch64 ] && PYC=(/data/scratch/ngom/activation/gh200_v1/venv/bin/python)
         HF=/data/scratch-fast/ngom/sec45/hf; export HOME=$W/home;;            # AFS home is invisible to CSAIL jobs
  orcd)  PYC=(/home/ngom/orcd/scratch/activation/rq_v1/code/.venv/bin/python); HF=/home/ngom/orcd/scratch/activation/hf; export HOME=${HOME:-/home/ngom};;
  *)     if [ -x "$HOME/sky_workdir/.venv/bin/python" ]; then PYC=("$HOME/sky_workdir/.venv/bin/python"); else PYC=(uv run --frozen --project "$HOME/sky_workdir" python); fi; HF=${HF_HOME:-$HOME/.cache/huggingface};;
esac
[ -n "${SEC45_PY:-}" ] && read -ra PYC <<< "$SEC45_PY"
HF=${SEC45_HF_HOME:-$HF}
USE_S3=${SEC45_USE_S3:-$([ $CL = ec2 ] && echo 1 || echo 0)}   # never on CSAIL / ORCD (no credentials there, and none must be put there)
D=$W/runs/$RUN
mkdir -p $W/code $W/data $W/init $W/runs $W/triton_cache $W/home || no "cannot write under $W"
if [ -e $D/DONE ]; then echo "$RUN is finished ($D/DONE: $(cat $D/DONE)); nothing to do"; exit 0; fi
SLOT=$(ls $D/sync/AC_MODELS/*/partial_epoch.json 2>/dev/null | head -1)
TRAINED=0; [ -f $D/sync/ckpt/final/meta.json ] && [ -f $D/sync/$RUN.stats.json ] && TRAINED=1   # training finished, an eval / DONE step did not
if [ -d $D ] && [ -z "$SLOT" ] && [ $TRAINED = 0 ] && ls $D/sync/AC_MODELS/*/completed_epoch.json >/dev/null 2>&1; then
  no "$D: the epoch was published but the run did not finish writing its outputs (killed during the end-of-run save): needs a look, not a restart"; fi
[ -d $D ] && [ -z "$SLOT" ] && [ $TRAINED = 0 ] && mv $D $D.prev_$(date +%s)          # nothing to continue from: start over (the old folder is kept)
mkdir -p $D/logs $D/eval
ATTEMPT=$(( $(ls $D/logs/train_a*.log 2>/dev/null | wc -l) + 1 ))
exec > >(tee -a $D/logs/job.log) 2>&1
say() { echo "$(date -u +%FT%TZ) [$RUN] $*"; }
[ $TRAINED = 1 ] && say "attempt $ATTEMPT: training already finished; evals and DONE only"
if [ -n "$SLOT" ]; then say "attempt $ATTEMPT: RESUME from the recovery slot $SLOT ($(tr -d '\n ' < $SLOT))"
elif [ $TRAINED = 0 ]; then say "attempt $ATTEMPT: fresh start"; fi
GPU_NAME=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1)
say "start on $(hostname) ($CL, job ${SLURM_JOB_ID:-none}): GPU '$GPU_NAME'; work $D; python ${PYC[*]}"
# ---- GPU: the values were measured on one GPU type ----
if [ "${SEC45_ALLOW_CPU:-0}" != 1 ]; then
  case $GPU_MATCH in
    exact:*)    IFS='|' read -ra OKN <<< "${GPU_MATCH#exact:}"; ok=0; for n in "${OKN[@]}"; do [ "$GPU_NAME" = "$n" ] && ok=1; done
                [ $ok = 1 ] || no "GPU '$GPU_NAME' is not one of '${GPU_MATCH#exact:}' (the GPU these values were planned on)";;
    contains:*) [[ "$GPU_NAME" == *"${GPU_MATCH#contains:}"* ]] || no "GPU '$GPU_NAME' does not contain '${GPU_MATCH#contains:}'";;
    *) no "GPU_MATCH '$GPU_MATCH'";;
  esac
else say "SEC45_ALLOW_CPU=1: no GPU check (CPU test only)"; fi
# ---- free disk: two recovery slots while one replaces the other (pair + optimizer.pt each) + kept pairs + 10 GB ----
case $KIND in recon) NCK=1;; task) NCK=2;; *) NCK=1;; esac       # R: ckpt/final; S/T: ckpt/final + the pair under eval
NEED_GB=$(awk -v p=$PAIR_GB -v o=$OPT_GB -v n=$NCK 'BEGIN{printf "%d", 2*(p+o)+p*n+10}')
FREE_GB=$(df -Pk $W | awk 'NR==2{printf "%d", $4/1048576}')
say "disk: $FREE_GB GB free under $W, about $NEED_GB GB needed (2 recovery slots of $PAIR_GB + $OPT_GB GB, $NCK kept pairs, 10 GB)"
[ "$FREE_GB" -ge "$NEED_GB" ] || no "not enough free disk under $W ($FREE_GB GB < $NEED_GB GB)"
# ---- S3 (EC2 only) ----
s3() { return 1; }
if [ "$USE_S3" = 1 ]; then
  cat > $W/s3x.py <<'S3X_EOF'
"""
Minimal S3 transfer for the section 4.5 jobs (boto3, default credential chain: environment, ~/.aws, instance profile; nothing is
printed about credentials). A transfer skips a file only when the other side has the same size AND is at least as new (2026-11-10 fix:
size alone left same-size files stale on S3, e.g. a recovery slot's state.json / partial_epoch.json / optimizer.pt, so a reclaimed spot
node resumed from an old slot). NEVER uploads optimizer.pt unless S3X_ALLOW_OPTIMIZER=1; putdir skips *.tmp / *.part files and
folders, uploads the slot pointers (state.json, partial_epoch.json) after everything else and a DONE file last.

  python s3x.py get    s3://BUCKET/KEY        LOCAL_FILE
  python s3x.py getdir s3://BUCKET/PREFIX/    LOCAL_DIR          (every object under the prefix, same relative paths)
  python s3x.py putdir LOCAL_DIR              s3://BUCKET/PREFIX/ [--exclude NAME ...]   (relative paths kept; skips symlinks)
  python s3x.py put    LOCAL_FILE             s3://BUCKET/KEY
  python s3x.py check                         (exit 0 when boto3 and credentials are usable)
Exit code 3: no boto3 / no credentials (the caller falls back or keeps outputs local).
"""
import os
import sys
from pathlib import Path

NEVER = set() if os.environ.get("S3X_ALLOW_OPTIMIZER") == "1" else {"optimizer.pt"}   # EC2 spot resume uploads the recovery slot


def split(url):
    assert url.startswith("s3://"), url
    bucket, _, key = url[5:].partition("/")
    return bucket, key


def client():
    try:
        import boto3
        from boto3.s3.transfer import TransferConfig
    except ImportError:
        print("s3x: boto3 is not installed", file=sys.stderr)
        sys.exit(3)
    session = boto3.session.Session()
    if session.get_credentials() is None:
        print("s3x: no AWS credentials on this machine", file=sys.stderr)
        sys.exit(3)
    return session.client("s3"), TransferConfig(multipart_threshold=64 * 2**20, multipart_chunksize=64 * 2**20, max_concurrency=8)


POINTERS = {"state.json", "partial_epoch.json"}                  # recovery-slot pointers: uploaded after the slot they point to


def head(s3, bucket, key):
    """(size, last-modified epoch seconds) of an object, or (None, None)."""
    try:
        h = s3.head_object(Bucket=bucket, Key=key)
        return h["ContentLength"], h["LastModified"].timestamp()
    except Exception:
        return None, None


def size_of(s3, bucket, key):
    return head(s3, bucket, key)[0]


def get(s3, config, url, local):
    bucket, key = split(url)
    local = Path(local)
    remote, modified = head(s3, bucket, key)
    if remote is None:
        raise SystemExit(f"s3x: missing {url}")
    if local.is_file() and local.stat().st_size == remote and local.stat().st_mtime >= modified:
        return 0
    local.parent.mkdir(parents=True, exist_ok=True)
    temporary = local.with_name(local.name + ".part")
    s3.download_file(bucket, key, str(temporary), Config=config)
    temporary.rename(local)
    return 1


def main():
    if len(sys.argv) < 2:
        raise SystemExit(__doc__)
    command, args = sys.argv[1], sys.argv[2:]
    s3, config = client()
    if command == "check":
        return
    if command == "get":
        get(s3, config, args[0], args[1])
    elif command == "getdir":
        bucket, prefix = split(args[0].rstrip("/") + "/")
        count = 0
        for page in s3.get_paginator("list_objects_v2").paginate(Bucket=bucket, Prefix=prefix):
            for item in page.get("Contents", []):
                if Path(item["Key"]).name in NEVER:
                    continue
                count += get(s3, config, f"s3://{bucket}/{item['Key']}", Path(args[1]) / item["Key"][len(prefix):])
        print(f"s3x: {count} files fetched from {args[0]}")
    elif command in ("put", "putdir"):
        exclude = set(NEVER)
        if "--exclude" in args:
            exclude |= set(args[args.index("--exclude") + 1:])
            args = args[:args.index("--exclude")]
        source, (bucket, prefix) = Path(args[0]), split(args[1])
        files = [(source, prefix)] if command == "put" else []
        if command == "putdir":
            prefix = prefix.rstrip("/") + "/"
            for folder, dirs, names in os.walk(source):
                dirs[:] = [d for d in dirs if d not in exclude and not d.endswith((".tmp", ".part"))]     # half-written folders (link_pair's NAME.tmp)
                for name in names:
                    path = Path(folder) / name
                    if name in exclude or path.is_symlink() or not path.is_file() or name.endswith((".part", ".tmp")):
                        continue
                    files.append((path, prefix + str(path.relative_to(source))))
        files.sort(key=lambda entry: (entry[0].name == "DONE", entry[0].name in POINTERS))   # pointers after their slots; DONE last (its presence implies the rest)
        sent = 0
        for path, key in files:
            if path.name in NEVER:
                continue
            remote, modified = head(s3, bucket, key)
            if remote == path.stat().st_size and modified >= path.stat().st_mtime:
                continue
            s3.upload_file(str(path), bucket, key, Config=config)
            sent += 1
        print(f"s3x: {sent} of {len(files)} files uploaded to s3://{bucket}/{prefix}")
    else:
        raise SystemExit(__doc__)


if __name__ == "__main__":
    main()
S3X_EOF
  S3PY=()
  for c in "${PYC[*]}" python3; do read -ra cand <<< "$c"; if "${cand[@]}" -c 'import boto3' 2>/dev/null; then S3PY=("${cand[@]}"); break; fi; done
  [ ${#S3PY[@]} = 0 ] && command -v uv >/dev/null && uv run --no-project --with boto3 python -c 'import boto3' 2>/dev/null && S3PY=(uv run --no-project --with boto3 python)
  if [ ${#S3PY[@]} -gt 0 ] && "${S3PY[@]}" $W/s3x.py check; then s3() { "${S3PY[@]}" $W/s3x.py "$@"; }; say "S3 on ($S3)"
  else USE_S3=0; say "S3 requested but not usable (no boto3 or no credentials): pre-staged inputs only"; fi
else say "S3 off: pre-staged inputs under $W, outputs stay in $D (jobs/pull.sh)"; fi
upload() { [ "$USE_S3" = 1 ] && s3 putdir $D $S3/runs/$RUN/ --exclude AC_MODELS LORAS teacher_snapshots optimizer.pt AUTOTUNE; true; }
# ---- code ----
STEM=${BUNDLE%.tar.gz}; C=$W/code/$STEM
if [ ! -f $C/MANIFEST.json ]; then
  [ -f $W/code/$BUNDLE ] || { s3 get $S3/code/$BUNDLE $W/code/$BUNDLE && s3 get $S3/code/$BUNDLE.sha256 $W/code/$BUNDLE.sha256; }
  (cd $W/code && sha256sum -c $BUNDLE.sha256) || no "code bundle $W/code/$BUNDLE missing or its sha256 does not match (jobs/stage.sh)"
  rm -rf $C.tmp.$$; mkdir -p $C.tmp.$$ && tar -xzf $W/code/$BUNDLE -C $C.tmp.$$ && { mv -T $C.tmp.$$ $C 2>/dev/null || rm -rf $C.tmp.$$; }   # per-job temp dir: two jobs starting together on a new bundle raced on one $C.tmp (2026-11-11)
  [ -f $C/MANIFEST.json ] || no "cannot unpack the code bundle"
fi
say "code $C (git $(grep -o '"git_head": "[0-9a-f]*' $C/MANIFEST.json | cut -c14-25))"
# ---- data ----
need() { [ -f "$2/$3" ] || s3 getdir $S3/data/$1/ $2 || true; [ -f "$2/$3" ] || no "data $2/$3 is missing (jobs/stage.sh)"; }
RD=$W/data/$RECON_DATA; TD=$W/data/$TASK_DATA
needtask() { need $TASK_DATA $TD train.jsonl; need $TASK_DATA $TD dev200.jsonl; need $TASK_DATA $TD $EVAL_SPLIT.jsonl; need $TASK_DATA $TD hotpotqa.corpus.jsonl.gz; }
case $KIND in recon) need $RECON_DATA $RD material.json.gz;; task) needtask;; probe) need $RECON_DATA $RD material.json.gz; needtask;; esac
# ---- T: R's final pair, complete and current ----
START=(--fresh)
if [ "$INIT" != fresh ]; then
  I=${SEC45_INIT_PAIR:-$W/init/${INIT}_final}
  if [ ! -f $I/DONE ] && [ -f $W/runs/$INIT/DONE ] && [ -d $W/runs/$INIT/sync/ckpt/final ]; then      # R ran on this cluster: hard-link its pair
    rm -rf $I.tmp; cp -al $W/runs/$INIT/sync/ckpt/final $I.tmp && cp $W/runs/$INIT/DONE $I.tmp/DONE && rm -rf $I && mv $I.tmp $I && say "R's pair linked from $W/runs/$INIT"
  fi
  if [ ! -f $I/DONE ] && [ "$USE_S3" = 1 ]; then
    rm -rf $I; s3 getdir $S3/runs/$INIT/sync/ckpt/final/ $I && s3 get $S3/runs/$INIT/DONE $I/DONE || true
  fi
  [ -f $I/DONE ] || no "R's DONE marker $I/DONE is missing: R is not finished, or its pair is not staged (jobs/stage_init.sh CLUSTER $INIT)"
  [ -f $I/meta.json ] && [ -f $I/ac/ac_modules.pt ] || no "the starting pair $I is incomplete (meta.json, ac/ac_modules.pt)"
  if [ -f $W/runs/$INIT/DONE ] && ! cmp -s $W/runs/$INIT/DONE $I/DONE; then no "stale $I: its DONE differs from $W/runs/$INIT/DONE (re-stage, or delete $I)"; fi
  "${PYC[@]}" -c "import json,sys; d=json.load(open('$I/DONE')); m=json.load(open('$I/meta.json'))
ok = d.get('valid') is True or '${SEC45_ALLOW_INVALID_INIT:-0}' == '1'
sys.exit(0 if ok and d.get('update') == m.get('update') else 5)" || no "R's DONE ($(cat $I/DONE)) is not a valid finished run, or its update differs from meta.json ($(cat $I/meta.json))"
  "${PYC[@]}" $C/kit/pairhash.py $I --check $I/DONE || no "the pair in $I does not match R's DONE (incomplete or stale copy)"
  START=(--pair $I/ac $I/reader); say "starting pair $I: R's DONE $(cat $I/DONE)"
fi
# ---- environment ----
export HF_HOME=$HF PYTHONUNBUFFERED=1 TZ=UTC TOKENIZERS_PARALLELISM=false PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True TRITON_CACHE_DIR=$W/triton_cache
export PYTHONPATH=$C:$C/kit:$C/rq_kit:$C/bench CQA_BENCH=$C/bench SEC45_RQ_KIT=$C/rq_kit RQ_THINKING=0 QA4B_READER=$READER_ID QA4B_SIDE=${ENCODER_ID:-$READER_ID} QA4B_RANK=128
if [ -n "$ENCODER_ID" ]; then export SEC45_ENCODER=$ENCODER_ID; else unset SEC45_ENCODER; fi
if [ -n "$RES_LAYERS" ]; then export SEC45_RES_LAYERS=$RES_LAYERS; else unset SEC45_RES_LAYERS; fi
if [ -n "$TASK_K" ]; then export SEC45_K=$TASK_K; else unset SEC45_K; fi
if [ "$LINEAR_SKIP" = 1 ]; then export SEC45_LINEAR_SKIP=1; else unset SEC45_LINEAR_SKIP; fi
if [ -n "$RATIO" ]; then export SEC45_RATIO=$RATIO; else unset SEC45_RATIO; fi
if [ -n "$TARGETS" ]; then [ -f $W/$TARGETS ] || no "target replies $W/$TARGETS missing"; export SEC45_TARGETS=$W/$TARGETS; fi   # unset: an inherited SEC45_TARGETS (rq_ac_node.sh RQ_TARGETS=1) still applies
unset HF_TOKEN HUGGING_FACE_HUB_TOKEN
case $MODE in in) export QA4B_LAYERS=none QA4B_KV=0;; res) export QA4B_LAYERS=3,7,11,15,19,23,27,31,35 QA4B_KV=0;; kv) export QA4B_LAYERS=none QA4B_KV=1;; *) no "MODE $MODE";; esac
for MID in $READER_ID $ENCODER_ID; do        # v6: the encoder's weights too (unauthenticated downloads can stall: 3 tries of 15 min)
CACHED="from huggingface_hub import try_to_load_from_cache as t; import sys; sys.exit(0 if all(isinstance(t('$MID', f), str) for f in ('config.json', 'tokenizer_config.json')) else 1)"   # docs-only gaps (LICENSE, README) do not matter
if [ ! -d "$MID" ] && ! "${PYC[@]}" -c "$CACHED" >/dev/null 2>&1; then
  case $CL in csail|orcd) no "$MID is not in $HF_HOME (jobs/stage.sh puts it there)";; esac
  for try in 1 2 3; do timeout 900 "${PYC[@]}" -c "from huggingface_hub import snapshot_download as s; s('$MID', token=False)" && break; done
  "${PYC[@]}" -c "$CACHED" >/dev/null 2>&1 || no "cannot get $MID into $HF_HOME"
fi
done
export HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1
UPLOADER=
[ "$USE_S3" = 1 ] && { ( while sleep 900; do upload > /dev/null 2>&1; done ) & UPLOADER=$!; }
trap '[ -n "$UPLOADER" ] && kill $UPLOADER 2>/dev/null; [ "$USE_S3" = 1 ] && { say "final upload"; upload; }' EXIT
TRAIN=("${PYC[@]}" $C/kit/sec45_train.py --mode $MODE --epu $EPU --encoder-lr $ENC_LR --reader-lr $READER_LR --penalty-weight $PENALTY --seed $SEED ${LOSS:+--loss $LOSS})
EVAL=("${PYC[@]}" $C/kit/sec45_eval.py --mode $MODE --data $TD --split $EVAL_SPLIT --batch 32 --max-new $EVAL_MAX_NEW ${EVAL_K:+--k $EVAL_K})
FAILED=0
# ---- run ----
case $KIND in
probe)    # 23 updates each: the 24 longest items first (peak memory), then random ones (speed); the penalty as in the real runs
  for spec in "recon 1" "recon 2" "task 1" "task 2" "task 4"; do read -r k mb <<< "$spec"; name=P0_${MODE}_${k}_mb$mb; data=$RD; [ $k = task ] && data=$TD
    save=(--no-save); [ "$k $mb" = "task 2" ] && save=(--ckpt-every 1000)
    say "probe $name"
    ACTIVATION_SYNC_ROOT=$D/sync/$name "${TRAIN[@]}" --kind $k --data $data --fresh --name $name --steps 23 --longest-first 3 --warmup 5 --report-every 1000 \
      --held-panel 32 --micro-batch $mb --seconds 1500 "${save[@]}" > $D/logs/$name.log 2>&1
    say "probe $name exit $? ($(grep -o '"effective_seconds_per_update": [0-9.]*\|"peak_gb": [0-9.a-z]*' $D/sync/$name/$name.stats.json 2>/dev/null | tr '\n' ' '))"
  done
  P=$D/sync/P0_${MODE}_task_mb2/ckpt/final
  if [ -d $P ]; then say "decode probe: 64 dev questions, greedy"
    "${EVAL[@]}" --pair $P/ac $P/reader --out $D/sync/eval/probe_decode.jsonl --limit 64 --label probe > $D/logs/P0_decode.log 2>&1 || FAILED=1; fi
  "${PYC[@]}" $C/kit/sec45_probe_summary.py --mode $MODE --dir $D/sync > $D/logs/P0_summary.log 2>&1 || FAILED=1
  cp $D/sync/probe_summary_$MODE.json $D/ 2>/dev/null; cat $D/logs/P0_summary.log
  rm -rf $D/sync/P0_${MODE}_task_mb2/AC_MODELS $D/sync/P0_${MODE}_task_mb2/LORAS $D/sync/P0_${MODE}_task_mb2/ckpt;;   # a 23-update pair: not kept
recon)
  TLOG=$D/logs/train_a$ATTEMPT.log; ln -sfn train_a$ATTEMPT.log $D/logs/train.log
  [ $TRAINED = 1 ] || ACTIVATION_SYNC_ROOT=$D/sync "${TRAIN[@]}" --kind recon --data $RD "${START[@]}" --name $RUN --steps $STEPS --seconds $TRAIN_SECONDS \
    --ckpt-every $CKPT_EVERY --micro-batch $MICRO --report-every $REPORT_EVERY --warmup $WARMUP --resume-if-possible --keep-steps final > $TLOG 2>&1 || FAILED=1
  say "training exit $FAILED: $(tail -n 1 $TLOG | cut -c1-400)";;
task)
  if [ "$INIT" != fresh ] && [ "$STEP0_EVAL" = 1 ] && [ ! -f $D/eval/u00000.summary.json ]; then say "accuracy at update 0 (the starting pair)"
    "${EVAL[@]}" --pair $I/ac $I/reader --out $D/eval/u00000.jsonl --label ${RUN}_u0 > $D/logs/eval_u00000.log 2>&1 || FAILED=1; fi
  # eval watcher: each K-update pair in ckpt/ (not the end: that one becomes ckpt/final) is evaluated on the same GPU while training
  # continues, then deleted; a pair whose eval fails is kept and the run is marked FAILED. A resumed attempt picks up leftovers.
  eval_pending() {   # eval_pending [final]: during training an eval that failed once is not retried (marker u<N>.failed); the final pass retries it once
    local Q u U rc=0
    for Q in $D/sync/ckpt/step_[0-9][0-9][0-9][0-9][0-9]; do [ -d "$Q" ] || continue
      U=${Q##*_}; u=$((10#$U)); [ $u -ge $STEPS ] && continue
      if [ -f $D/eval/u$U.failed ] && [ "${1:-}" != final ]; then rc=1; continue; fi
      if [ ! -f $D/eval/u$U.summary.json ]; then say "accuracy at update $u (eval watcher)"; rm -f $D/eval/u$U.failed
        "${EVAL[@]}" --pair $Q/ac $Q/reader --out $D/eval/u$U.jsonl --label ${RUN}_u$u > $D/logs/eval_u$U.log 2>&1 || { say "eval of update $u FAILED (pair kept)"; touch $D/eval/u$U.failed; rc=1; continue; }
      fi
      [ -f $D/eval/u$U.summary.json ] && rm -rf $Q && say "update $u: $(head -c 120 $D/eval/u$U.summary.json | tr -d '\n ') (pair deleted)"
    done; return $rc; }
  TLOG=$D/logs/train_a$ATTEMPT.log; ln -sfn train_a$ATTEMPT.log $D/logs/train.log
  if [ $TRAINED = 1 ]; then echo "training already finished (see the earlier train_a*.log)" > $TLOG; sleep 0 & else
  ACTIVATION_SYNC_ROOT=$D/sync "${TRAIN[@]}" --kind task --data $TD "${START[@]}" --name $RUN --steps $STEPS --seconds $TRAIN_SECONDS \
    --ckpt-every $CKPT_EVERY --micro-batch $MICRO --report-every $REPORT_EVERY --warmup $WARMUP --resume-if-possible --keep-steps all > $TLOG 2>&1 &
  fi
  TPID=$!
  while kill -0 $TPID 2>/dev/null; do eval_pending || true; sleep 60; done     # a failure here is retried by the final pass, which decides
  wait $TPID || FAILED=1
  say "training exit $FAILED: $(tail -n 1 $TLOG | cut -c1-400)"
  eval_pending final || FAILED=1
  Q=$D/sync/ckpt/final
  if [ -f $D/eval/final.summary.json ]; then say "accuracy at the end: already evaluated"
  elif [ -d $Q ]; then say "accuracy at the end ($(cat $Q/meta.json 2>/dev/null))"
    "${EVAL[@]}" --pair $Q/ac $Q/reader --out $D/eval/final.jsonl --label ${RUN}_final > $D/logs/eval_final.log 2>&1 || FAILED=1
  else FAILED=1; say "no final pair"; fi
  for f in $D/eval/*.summary.json; do [ -f $f ] && say "$(basename $f .summary.json): $(head -c 300 $f | tr -d '\n ')"; done;;
esac
# optimizer.pt: only while a recovery slot is published (the run can still continue); once training completed (the trainer
# removed the slot at the end) drop every copy. A failed or stopped attempt keeps its slot for the next job.
if [ -z "$(ls $D/sync/AC_MODELS/*/partial_epoch.json 2>/dev/null)" ]; then find $D -name optimizer.pt -type f -delete 2>/dev/null
else say "recovery slot kept: $(ls $D/sync/AC_MODELS/*/partial_epoch.json) (resubmit this script to continue)"; fi
[ $FAILED = 0 ] || { say "end, FAILED (no DONE); disk $(du -sh $D | cut -f1)"; exit 1; }
# ---- DONE, last: ckpt/final is complete here; its hash lets T verify the exact pair it starts from ----
F=$D/sync/ckpt/final; [ $KIND = probe ] && F=
"${PYC[@]}" - "$D" "$RUN" "$KIND" "$MODE" "$F" "$C/kit" "$GPU_NAME" <<'PY' || { say "could not write DONE"; exit 1; }
import json, os, socket, sys, time
from pathlib import Path
d, run, kind, mode, final, kit, gpu = sys.argv[1:8]
sys.path.insert(0, kit)
from pairhash import pair_hash
out = {"run": run, "kind": kind, "mode": mode, "host": socket.gethostname(), "gpu": gpu, "job": os.environ.get("SLURM_JOB_ID"),
       "finished_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
       "attempts": 1 + sum(1 for _ in open(Path(d) / "sync" / f"{run}.resumes.jsonl")) if (Path(d) / "sync" / f"{run}.resumes.jsonl").exists() else 1}
if kind == "probe":
    out |= {"valid": True, "stop_reason": "complete"}
else:
    stats = json.loads((Path(d) / "sync" / f"{run}.stats.json").read_text())
    meta = json.loads((Path(final) / "meta.json").read_text())
    out |= {"stop_reason": stats["stop_reason"], "valid": bool(stats.get("valid")), "update": meta["update"], "planned_updates": meta["planned_updates"],
            "order_first_sha256": (stats.get("order_full") or stats.get("order_trained", {})).get("first_sha256"), "final_sha256": pair_hash(final)}
    if kind == "task":
        out["evals"] = {p.name.removesuffix(".summary.json"): json.loads(p.read_text()).get("acc") for p in sorted((Path(d) / "eval").glob("*.summary.json"))}
tmp = Path(d) / "DONE.tmp"
tmp.write_text(json.dumps(out) + "\n")
tmp.rename(Path(d) / "DONE")
print(json.dumps(out))
PY
if grep -q '"valid": true' $D/DONE; then say "end, valid; disk $(du -sh $D | cut -f1)"; exit 0; fi
say "end, INVALID (stop_reason $(grep -o '"stop_reason": "[^"]*"' $D/DONE)): see $D/DONE"; exit 3
